import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const $ = (id) => document.getElementById(id);
const canvas = $('world');
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 120);
const renderer = new THREE.WebGLRenderer({canvas, antialias:true, alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.65));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.17;
scene.background = new THREE.Color('#111719');
scene.fog = new THREE.FogExp2('#1b2525', .024);

const clock = new THREE.Clock();
const raycaster = new THREE.Raycaster();
const world = new THREE.Group(); scene.add(world);
const rainGroup = new THREE.Group(); scene.add(rainGroup);
const V = (x=0,y=0,z=0) => new THREE.Vector3(x,y,z);
const mat = (color, roughness=.85, metalness=0, extra={}) => new THREE.MeshStandardMaterial({color, roughness, metalness, ...extra});
const materials = {
  asphalt: mat('#333a38'), wet: mat('#252d2c',.3,.22), concrete: mat('#6b6b5d'), wall: mat('#827c68'), darkWall:mat('#414844'), rust:mat('#624638'), wood:mat('#533d2e'), glass:mat('#253a39',.24,.15,{emissive:'#182a27',emissiveIntensity:.3}), warmGlass:mat('#b47544',.25,0,{emissive:'#b47544',emissiveIntensity:.8}), cloth:mat('#343e3b'), skin:mat('#9f765d'), black:mat('#171b1b'), light:mat('#d6b77f',.25,0,{emissive:'#d6b77f',emissiveIntensity:1.2})
};
let player, playerLight, muzzle, worldObjects=[], enemies=[], targets=[], pickups=[], obstacles=[], rainPositions, rainVelocities;
let yaw=0, health=100, loadedAmmo=6, reserveAmmo=18, medkits=1, flashlightOn=true, running=false;
let currentChapter=0, stage=0, chapterFlags={}, active=false, paused=false, inventoryOpen=false, dialogueQueue=[], dialogueLock=false;
let targetNear=null, lastSave=null, lastShot=0, hurtCooldown=0, toastTimer=0, chapterCardTimer=0, saveData=null;
const keys = Object.create(null);
const chapterInfo = [
  {name:'THE SILENT TOWN', quote:'“The rain has a way of washing away the footprints. Not the voices.”', objective:'Find a way into the clinic', detail:'Isha’s last message came from the old dispensary.'},
  {name:'WARD 9', quote:'“They called it a fever. They were already building the cure.”', objective:'Restore power to the east wing', detail:'The lift is dead. Find a fuse and wake the generator.'},
  {name:'PAPER WALLS', quote:'“Every missing person had a file. Every file had the same signature.”', objective:'Find Isha’s incident report', detail:'The station records room is locked. Search the evidence desk.'},
  {name:'THE ECLIPSE WING', quote:'“If the lights go out, do not follow the voice.”', objective:'Align the containment relays', detail:'Three relays feed the central isolation door.'},
  {name:'THE LAST SANCTUARY', quote:'“You came all this way. You should know what she became.”', objective:'Find the source of Isha’s signal', detail:'The voice is coming from behind the sealed chamber.'}
];

function mesh(geometry, material, parent=world, x=0,y=0,z=0, cast=true, receive=true) {
  const o = new THREE.Mesh(geometry, material); o.position.set(x,y,z); o.castShadow=cast; o.receiveShadow=receive; parent.add(o); worldObjects.push(o); return o;
}
function box(parent,x,y,z,w,h,d,material,rx=0,ry=0,rz=0){const o=mesh(new THREE.BoxGeometry(w,h,d),material,parent,x,y,z);o.rotation.set(rx,ry,rz);return o;}
function cylinder(parent,x,y,z,r1,r2,h,material,segments=12){const o=mesh(new THREE.CylinderGeometry(r1,r2,h,segments),material,parent,x,y,z);return o;}
function group(parent=world,x=0,y=0,z=0){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);return g;}

function makePlayer(){
  player=group(scene,0,0,4); player.name='Arjun';
  const torso=mesh(new THREE.CapsuleGeometry(.34,.55,4,8),mat('#44504b'),player,0,1.05,0); torso.scale.set(1,.95,.75);
  const coat=mesh(new THREE.BoxGeometry(.61,.53,.42),mat('#303a36'),player,0,.98,0); coat.rotation.x=-.05;
  mesh(new THREE.SphereGeometry(.22,12,10),materials.skin,player,0,1.78,-.03);
  mesh(new THREE.CylinderGeometry(.225,.23,.09,12),mat('#242725'),player,0,1.94,-.02);
  const legL=mesh(new THREE.CapsuleGeometry(.115,.47,3,7),mat('#242b29'),player,-.16,.43,0);
  const legR=mesh(new THREE.CapsuleGeometry(.115,.47,3,7),mat('#242b29'),player,.16,.43,0);
  const armL=mesh(new THREE.CapsuleGeometry(.1,.42,3,7),mat('#38413d'),player,-.4,1.05,-.02);armL.rotation.z=-.1;
  const armR=mesh(new THREE.CapsuleGeometry(.1,.42,3,7),mat('#38413d'),player,.4,1.04,-.05);armR.rotation.z=.1;
  const gun=group(player,.34,1.03,-.35);gun.name='weapon';box(gun,0,0,0,.12,.12,.38,mat('#222828',.35,.55));box(gun,0,-.1,.08,.08,.2,.1,mat('#393632'));gun.rotation.x=-.1;
  muzzle=new THREE.PointLight('#ffbb7a',0,4);muzzle.position.set(.34,1.08,-.9);player.add(muzzle);
  playerLight=new THREE.SpotLight('#d9d4b8',65,24,Math.PI/8,.42,1.3);playerLight.position.set(.1,1.58,-.35);playerLight.target.position.set(0,1.1,-7);player.add(playerLight);player.add(playerLight.target);
  player.userData={legL,legR,armL,armR,walk:0,velocity:V()};
}

function addRain(){
  const count=1400; rainPositions=new Float32Array(count*3);rainVelocities=new Float32Array(count);
  for(let i=0;i<count;i++){rainPositions[i*3]=(Math.random()-.5)*38;rainPositions[i*3+1]=Math.random()*18;rainPositions[i*3+2]=(Math.random()-.5)*32;rainVelocities[i]=10+Math.random()*8;}
  const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(rainPositions,3));
  const points=new THREE.Points(geo,new THREE.PointsMaterial({color:'#a8b8b2',size:.055,transparent:true,opacity:.39,depthWrite:false}));rainGroup.add(points);
}

function addGround(chapter){
  const groundColor=['#41433b','#53605b','#4a4b43','#343b3a','#393b36'][chapter];
  mesh(new THREE.PlaneGeometry(64,46),mat(groundColor,.95),world,0,-.11,0).rotation.x=-Math.PI/2;
  // cracked, wet road and its broken lane paint
  const road=mesh(new THREE.PlaneGeometry(50,9),materials.asphalt,world,0,-.045,0);road.rotation.x=-Math.PI/2;
  for(let x=-23;x<23;x+=4.5){const stripe=mesh(new THREE.PlaneGeometry(2.2,.085),mat('#b9ae86',.7,0,{transparent:true,opacity:.3}),world,x,-.025,0);stripe.rotation.x=-Math.PI/2;}
  // rain-dark puddles catch the sickly light
  for(let i=0;i<24;i++){let x=(Math.random()-.5)*45,z=(Math.random()-.5)*21;if(Math.abs(z)<5)z+=(z<0?-5:5);const p=mesh(new THREE.CircleGeometry(.35+Math.random()*1.25,18),mat('#77827a',.12,.18,{transparent:true,opacity:.15}),world,x,-.018,z,false);p.rotation.x=-Math.PI/2;p.scale.y=.35+Math.random()*.45;}
  for(const z of [-16,16])box(world,0,.9,z,55,1.8,.7,mat(chapter===3?'#3b4542':'#343b39'));
}

function makeBuilding(x,z,w,d,h,kind='house',seed=0){
  const g=group(world,x,0,z);const wallmat=kind==='hospital'?mat('#b1ad9c'):kind==='station'?mat('#736f61'):kind==='lab'?mat('#687574'):mat(seed%2?'#786e5e':'#625e52');
  box(g,0,h/2,0,w,h,d,wallmat);
  const roof=box(g,0,h+.08,0,w+.25,.22,d+.22,kind==='house'?mat('#403b34'):mat('#505956'));
  if(kind==='house'){roof.rotation.z=(seed%2?.13:-.11);}
  const cols=Math.max(2,Math.floor(w/2.5));
  for(let i=0;i<cols;i++){
    const wx=-w/2+(i+.5)*w/cols;
    if(Math.abs(wx)<.75){box(g,wx,1.15,d/2+.015,1.4,2.3,.08,materials.wood);box(g,wx,1.15,d/2+.07,1.16,2.02,.04,mat('#201e1b'));continue;}
    const wy=Math.min(h-1.25,2.35);
    box(g,wx,wy,d/2+.02,.78,1.02,.09,Math.random()<.32?materials.warmGlass:materials.glass);
    box(g,wx,wy,d/2+.08,.9,.09,.08,mat('#514d43'));box(g,wx,wy,d/2+.08,.07,1.1,.08,mat('#514d43'));
    if(kind==='station'||kind==='hospital'){box(g,wx,wy,d/2+.11,.06,1.02,.09,mat('#585e58'));}
  }
  if(kind==='hospital'||kind==='station'||kind==='lab'){
    for(let i=0;i<Math.floor(w/3);i++)box(g,-w/2+1.5+i*3,h+.25,0,.14,.3,d+.12,mat('#aeb5ae'));
  }
  if(kind==='hospital'){
    box(g,0,h+1.05,d/2+.05,w*.45,1.35,.22,mat('#e2e0d1'));
    box(g,0,h+1.05,d/2+.18,w*.42,.035,.04,mat('#75817c'));
  }
  if(kind==='station'){
    box(g,0,h+1.05,d/2+.05,w*.42,1.3,.22,mat('#d0c8b3'));
  }
  obstacles.push({x,z,r:Math.max(w,d)*.38});return g;
}

function addTownDressing(chapter){
  const types=chapter===1?['hospital','house','house','house']:chapter===2?['station','house','house']:chapter>=3?['lab','house','lab']:['house','house','house'];
  makeBuilding(13,-11,11,7,5.5,types[0],chapter);
  makeBuilding(-14,11,10,7,4.7,types[1]||'house',1);
  makeBuilding(1,-13,9,6,4.5,types[2]||'house',2);
  makeBuilding(-16,-11,8,6,4.2,types[3]||'house',3);
  makeBuilding(15,12,9,6,4.3,chapter===1?'house':types[1]||'house',4);
  // signature architecture and silhouettes vary by district
  if(chapter===0){
    // tilted roadside bus and a dry well, markers of the abandoned town
    const bus=group(world,-5,0,-6);box(bus,0,1.2,0,5.8,2.35,2.25,mat('#746b51'));box(bus,-.3,2.15,0,4.4,.4,2.08,mat('#4b514a'));for(let i=0;i<4;i++)mesh(new THREE.TorusGeometry(.38,.12,7,12),mat('#1d201f'),bus,-1.7+i*1.1,.38,1.14).rotation.y=Math.PI/2;
    cylinder(world,7,.25,-5,1.25,1.45,.5,mat('#676251'),14);cylinder(world,7,.64,-5,1.05,1.1,.3,materials.wet,14);
  } else if(chapter===1){
    // treatment beds visible through ruined ward windows
    for(let i=0;i<3;i++){box(world,9+i*2,.3,-9,.9,.2,1.7,mat('#d5d0c0'));cylinder(world,9+i*2,.8,-9,.045,.045,1.1,mat('#777e78'));}
    box(world,17,1.45,-11,3.8,2.8,.3,mat('#25312e'));box(world,17,2.15,-10.8,2.1,.3,.04,mat('#d8d1bd'));
  }else if(chapter===2){
    box(world,15,2.5,-11,4,.34,.25,mat('#c5bd9d'));for(let i=0;i<3;i++)box(world,14+i,2.5,-10.8,.8,.04,.05,materials.rust);
    // leaning flag pole
    cylinder(world,-20,4,7,.08,.1,8,mat('#555952'));box(world,-19,7,7,2.4,1.2,.04,mat('#744d3f'));
  }else if(chapter===3){
    for(const x of [-15,-5,5,15]){box(world,x,3,-10,.18,6,.18,mat('#a5a99e'));for(const z of [-7,0,7])box(world,x,3,z,.18,6,.18,mat('#a5a99e'));}
    for(let i=0;i<5;i++)cylinder(world,-11+i*5,.25,6,.55,.55,.45,mat('#555b57'));
  }else{
    // black-glass isolation structures and cable trunks
    for(let i=0;i<5;i++){box(world,-13+i*6,2.8,-11,2.4,5.6,.25,mat('#253431',.2,.35));box(world,-13+i*6,2.8,-10.84,1.7,4.9,.04,mat('#183b38',.18,.4,{emissive:'#0b2623',emissiveIntensity:.7}));}
    for(let x=-19;x<=19;x+=3)box(world,x,.1,-7,.13,.2,7,mat('#64716b'));
  }
  // broken street furniture, lamps and ragged tarpaulin shapes
  for(let i=0;i<6;i++){
    const x=-19+i*7.5,z=i%2?-6.5:6.5;
    cylinder(world,x,2.1,z,.07,.11,4.2,mat('#454843'));
    const lamp=mesh(new THREE.SphereGeometry(.16,8,8),materials.light,world,x,4.18,z,false);lamp.material=materials.light;
    const light=new THREE.PointLight('#d2a16a',i%3===0?8:0,8,2);light.position.set(x,3.9,z);world.add(light);
    if(i%2===0){const tarp=mesh(new THREE.PlaneGeometry(2.6,2),mat('#37403b',.9,0,{side:THREE.DoubleSide}),world,x,2.2,z+2);tarp.rotation.set(.7,0,.16);}
  }
  // roadside shrines - offerings half submerged in rain
  for(const x of [-22,22]){box(world,x,.65,0,1.25,1.3,.55,mat('#49443b'));box(world,x,.35,.32,.7,.5,.08,mat('#8c5142'));}
}

function makeTarget(data){
  const g=group(world,data.x,0,data.z);g.userData=data;g.name='objective-'+data.id;
  const glow=new THREE.PointLight('#d99f64',0,4,2);glow.position.y=1.1;g.add(glow);
  const ring=mesh(new THREE.TorusGeometry(.45,.025,5,24),mat('#d7a671',.5,.1,{emissive:'#aa713e',emissiveIntensity:.65}),g,0,.12,0,false);ring.rotation.x=Math.PI/2;
  const beam=mesh(new THREE.CylinderGeometry(.025,.3,1.3,12,1,true),new THREE.MeshBasicMaterial({color:'#d6a36d',transparent:true,opacity:.11,side:THREE.DoubleSide,depthWrite:false}),g,0,.78,0,false,false);
  const object=group(g,0,.6,0);g.userData.object=object;
  const steel=mat('#a6a394',.3,.65),brass=mat('#b88a4d',.25,.7),paper=mat('#d5c9ab');
  if(data.kind==='key'){
    cylinder(object,0,.18,0,.055,.055,.45,brass,10).rotation.z=Math.PI/2;mesh(new THREE.TorusGeometry(.14,.04,6,12),brass,object,-.3,.18,0);box(object,.23,.18,0,.22,.07,.07,brass);
  }else if(data.kind==='fuse'){
    box(object,0,.14,0,.32,.35,.3,mat('#9e7042'));box(object,0,.37,0,.16,.12,.17,mat('#d2b778'));box(object,0,.14,.17,.19,.09,.04,mat('#392f23'));
  }else if(data.kind==='card'){
    box(object,0,.16,0,.49,.08,.32,mat('#b4b1a1',.3,.2));box(object,-.06,.22,0,.2,.012,.22,mat('#49665d'));box(object,.18,.22,0,.09,.012,.2,mat('#826b4a'));
  }else if(data.kind==='document'){
    box(object,0,.13,0,.5,.055,.38,paper);for(let i=0;i<3;i++)box(object,-.04,.17,-.1+i*.09,.3-i*.03,.008,.012,mat('#675f4e'));
  }else if(data.kind==='relay'){
    box(object,0,.36,0,.38,.68,.26,mat('#49534e',.4,.4));box(object,0,.45,.15,.19,.1,.025,mat('#ad634c',.3,.2,{emissive:'#853322',emissiveIntensity:.7}));for(let i=0;i<2;i++)cylinder(object,-.12+i*.24,.73,0,.035,.035,.14,steel,8);
  }else if(data.kind==='specimen'){
    cylinder(object,0,.3,0,.18,.18,.62,mat('#b4b2a1',.2,.35,{transparent:true,opacity:.58}));cylinder(object,0,.3,0,.12,.12,.34,mat('#7e9c79',.15,0,{emissive:'#597251',emissiveIntensity:.7}));cylinder(object,0,.63,0,.21,.21,.08,brass,10);
  }else if(data.kind==='door'){
    box(object,0,1,0,2.6,2.4,.3,mat('#2a302e',.45,.65));box(object,0,1,.18,2.2,2.05,.08,mat('#39423e',.3,.45));box(object,0,2.25,.1,1.6,.15,.16,mat('#9a573f',.3,.3,{emissive:'#703622',emissiveIntensity:.4}));
  }else{
    box(object,0,.15,0,.34,.3,.2,steel);cylinder(object,0,.34,0,.11,.11,.08,brass,10);
  }
  g.userData.visual={glow,ring,beam,object};targets.push(g);return g;
}

const chapterTargets=[
  [
    {id:'voice',x:-9,z:0,stage:0,label:'Play Isha’s last voice message',kind:'document'},
    {id:'key',x:3,z:6,stage:1,label:'Take the clinic key',kind:'key'},
    {id:'gate',x:20,z:0,stage:2,label:'Unlock the clinic entrance',kind:'door'}
  ],
  [
    {id:'fuse',x:-10,z:-5,stage:0,label:'Take the east-wing fuse',kind:'fuse'},
    {id:'generator',x:2,z:5,stage:1,label:'Install the fuse in the generator',kind:'relay'},
    {id:'card',x:13,z:-4,stage:2,label:'Take the elevator access card',kind:'card'},
    {id:'lift',x:21,z:0,stage:3,label:'Use the card at the service lift',kind:'door'}
  ],
  [
    {id:'key',x:-10,z:5,stage:0,label:'Find the evidence-room key',kind:'key'},
    {id:'report',x:4,z:-5,stage:1,label:'Read Isha’s incident report',kind:'document'},
    {id:'exit',x:20,z:0,stage:2,label:'Open the records vault',kind:'door'}
  ],
  [
    {id:'relay-a',x:-11,z:-5,stage:0,label:'Align containment relay 01',kind:'relay'},
    {id:'relay-b',x:1,z:5,stage:1,label:'Align containment relay 02',kind:'relay'},
    {id:'relay-c',x:12,z:-5,stage:2,label:'Align containment relay 03',kind:'relay'},
    {id:'door',x:21,z:0,stage:3,label:'Open the isolation door',kind:'door'}
  ],
  [
    {id:'signal',x:-10,z:0,stage:0,label:'Trace Isha’s signal',kind:'document'},
    {id:'sample',x:4,z:5,stage:1,label:'Recover the Eclipse sample',kind:'specimen'},
    {id:'chamber',x:20,z:0,stage:2,label:'Enter the sanctuary chamber',kind:'door'}
  ]
];

function makeEnemy(x,z,type='drowned'){
  const g=group(world,x,0,z);g.name='hostile';g.userData={hp:type==='warden'?4:2,type,mode:'wander',timer:Math.random()*2,attack:0,home:V(x,0,z),phase:Math.random()*6};
  const skin=mat(type==='warden'?'#77766b':'#6d7770',.95), wound=mat('#4b2824',.85), clothes=mat(type==='warden'?'#3b4039':'#48403a');
  const torso=mesh(new THREE.CapsuleGeometry(type==='warden'?.4:.32,type==='warden'?.75:.62,4,8),clothes,g,0,1.18,0);torso.rotation.z=.08;
  mesh(new THREE.SphereGeometry(.26,12,10),skin,g,.02,2.02,-.05);
  mesh(new THREE.BoxGeometry(.23,.05,.05),wound,g,.11,1.97,-.27);
  const arm1=mesh(new THREE.CapsuleGeometry(.12,.55,3,7),skin,g,-.43,1.2,-.08);arm1.rotation.z=-.42;
  const arm2=mesh(new THREE.CapsuleGeometry(.12,.63,3,7),skin,g,.43,1.18,.08);arm2.rotation.z=.5;
  const leg1=mesh(new THREE.CapsuleGeometry(.14,.55,3,7),clothes,g,-.17,.48,0);
  const leg2=mesh(new THREE.CapsuleGeometry(.14,.55,3,7),clothes,g,.17,.48,0);
  for(const s of [-1,1]){const eye=mesh(new THREE.SphereGeometry(.045,8,6),mat('#d9ae78',.2,0,{emissive:'#a75934',emissiveIntensity:2}),g,s*.1,2.03,-.265,false);}
  if(type==='warden'){
    const tendril=mesh(new THREE.CapsuleGeometry(.09,.8,3,6),wound,g,.55,1.7,-.02);tendril.rotation.z=-1.05;
    for(let i=0;i<3;i++)mesh(new THREE.SphereGeometry(.12,8,6),wound,g,.1+i*.15,2.26+Math.sin(i)*.08,.04,false);
  }
  const aura=new THREE.PointLight('#8c4031',1.8,4,2);aura.position.y=1.8;g.add(aura);
  g.userData.limbs={arm1,arm2,leg1,leg2};enemies.push(g);return g;
}

function buildChapter(index){
  currentChapter=index;stage=0;chapterFlags={};targets=[];enemies=[];obstacles=[];
  while(world.children.length){const c=world.children[0];world.remove(c);}
  worldObjects=[];world.clear();
  scene.background=new THREE.Color(['#111719','#17201f','#1a1c19','#111a19','#131917'][index]);
  scene.fog.color.set(['#1c2828','#27302d','#292a25','#1c2927','#1c2623'][index]);scene.fog.density=index===3?.031:.024;
  const hemi=new THREE.HemisphereLight(index===4?'#778c81':'#89918a','#26251f',index===1?.9:.73);world.add(hemi);
  const moon=new THREE.DirectionalLight('#b8c2b9',index===3?1.5:1.9);moon.position.set(-8,15,7);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);moon.shadow.camera.left=-26;moon.shadow.camera.right=26;moon.shadow.camera.top=20;moon.shadow.camera.bottom=-20;moon.shadow.bias=-.0002;world.add(moon);
  const fill=new THREE.DirectionalLight(index===4?'#87a38d':'#89909a',.6);fill.position.set(12,7,-10);world.add(fill);
  addGround(index);addTownDressing(index);
  // Subtle drifting fog banks are low, translucent sheets over the wet road.
  for(let i=0;i<8;i++){const fog=mesh(new THREE.PlaneGeometry(10,2.4),new THREE.MeshBasicMaterial({color:index===3?'#71807a':'#87918a',transparent:true,opacity:.028,depthWrite:false,side:THREE.DoubleSide}),world,(Math.random()-.5)*36,.32+(i%3)*.2,(Math.random()-.5)*13,false,false);fog.rotation.x=-.13;fog.userData.drift=(Math.random()-.5)*.11;}
  chapterTargets[index].forEach(makeTarget);
  if(index===0){makeEnemy(-3,1,'drowned');makeEnemy(11,7,'drowned');}
  if(index===1){makeEnemy(-1,-1,'drowned');makeEnemy(14,3,'drowned');}
  if(index===2){makeEnemy(5,1,'drowned');makeEnemy(-15,-4,'drowned');}
  if(index===3){makeEnemy(-3,-1,'drowned');makeEnemy(9,1,'warden');}
  if(index===4){makeEnemy(-1,-5,'warden');makeEnemy(12,6,'drowned');}
  // A lit silhouette and a route sign orient the player toward the active district.
  const sign=group(world,0,0,-18);box(sign,0,2,0,4,.9,.16,mat('#343c39'));box(sign,0,2.03,.1,3.55,.56,.05,mat('#aa8c64'));cylinder(sign,-1.7,1,0,.06,.06,2,mat('#343c39'));cylinder(sign,1.7,1,0,.06,.06,2,mat('#343c39'));
