function init(){
  const canvas=$('world');scene=new THREE.Scene();scene.background=new THREE.Color(0x090d10);scene.fog=new THREE.FogExp2(0x10191b,.032);
  camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,180);
  renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false,powerPreference:'high-performance'});
  renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;
  world=new THREE.Group();scene.add(world);scene.add(new THREE.HemisphereLight(0x9db6c0,0x1b1715,1.05));
  const moon=new THREE.DirectionalLight(0x9cb5bf,1.35);moon.position.set(-12,23,-8);moon.castShadow=true;moon.shadow.mapSize.set(1024,1024);scene.add(moon);
  const fill=new THREE.PointLight(0x54717c,22,44);fill.position.set(1,8,2);scene.add(fill);
  player=makePlayer();scene.add(player);playerLight=new THREE.SpotLight(0xc9d9d4,68,28,Math.PI/7,.5,1.3);playerLight.position.set(0,1.55,0);playerLightTarget=new THREE.Object3D();scene.add(playerLight,playerLightTarget);playerLight.target=playerLightTarget;
  muzzle=new THREE.PointLight(0xff9b54,0,9);scene.add(muzzle);
