const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1280,height:720},deviceScaleFactor:1});
 const errors=[],failed=[],responses=[];
 page.on('pageerror',e=>errors.push(String(e)));
 page.on('console',m=>{if(m.type()==='error')errors.push('console: '+m.text())});
 page.on('requestfailed',r=>failed.push(`${r.url()} ${r.failure()?.errorText}`));
 page.on('response',r=>{if(r.status()>=400)responses.push(`${r.status()} ${r.url()}`)});
 await page.goto('http://localhost:3002/',{waitUntil:'networkidle',timeout:45000});
 await page.waitForTimeout(1000);
 const init=await page.evaluate(()=>({title:document.title,loading:getComputedStyle(document.querySelector('#loading-screen')).display,webgl:document.querySelector('canvas').getContext('webgl2')!==null}));
 await page.click('#start-button');
 await page.keyboard.press('Enter');
 const fps=await page.evaluate(async()=>{let ticks=0,start=performance.now();return await new Promise(resolve=>{function f(){ticks++;if(performance.now()-start>=5000)resolve({frames:ticks,seconds:(performance.now()-start)/1000,fps:ticks/((performance.now()-start)/1000)});else requestAnimationFrame(f)}requestAnimationFrame(f)})});
 await page.screenshot({path:'/tmp/opencode/game.png'});
 console.log(JSON.stringify({init,fps,errors,failed,responses},null,2));
 await browser.close();
})();

