const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({headless:true,args:['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--no-sandbox']});
  const page = await browser.newPage({viewport:{width:1280,height:720},deviceScaleFactor:1});
  const errors=[];
  page.on('pageerror',e=>errors.push(String(e)));
  await page.route('**/game.js', async route => {
    let body=await (await route.fetch()).text();
    body=body.replace('const resolutionCap=/swiftshader|llvmpipe|softpipe/i.test(gpuName)?.55:1;','window.__gpuName=gpuName;const resolutionCap=/swiftshader|llvmpipe|softpipe/i.test(gpuName) ? .55 : 1;');
    body=body.replace('renderer.setPixelRatio(Math.min(devicePixelRatio||1,resolutionCap));','renderer.setPixelRatio(Math.min(devicePixelRatio||1,resolutionCap));window.__pixelRatio=renderer.getPixelRatio();');
    body=body.replace('init();\nfunction startGame','init();window.__gameTest={state:()=>({stage,currentChapter,health,medkits,loadedAmmo,reserveAmmo,player:{x:player.position.x,z:player.position.z},gpu:window.__gpuName,pixelRatio:window.__pixelRatio}),damage,interact,fire,reload,useMedkit,advanceDialogue,movePlayer};\nfunction startGame');
    await route.fulfill({body,contentType:'text/javascript'});
  });
  await page.goto('http://localhost:3002/',{waitUntil:'networkidle'});
  await page.click('#start-button');
  await page.keyboard.press('Enter');await page.keyboard.press('Enter');
  const start=await page.evaluate(()=>window.__gameTest.state());
  await page.evaluate(()=>{window.__gameTest.damage(35);});
  await page.keyboard.press('Tab');
  await page.locator('.inventory-slot button, button.inventory-slot').first().click().catch(()=>{});
  const afterHeal=await page.evaluate(()=>window.__gameTest.state());
  await page.keyboard.press('Escape');
  await page.keyboard.press('Space');
  const afterShot=await page.evaluate(()=>window.__gameTest.state());
  await page.keyboard.press('KeyR');
  const afterReload=await page.evaluate(()=>window.__gameTest.state());
  await page.locator('#save-button').click();
  const save=await page.evaluate(()=>JSON.parse(localStorage.getItem('last-sanctuary-save')));
  const mobile=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});
  await mobile.goto('http://localhost:3002/',{waitUntil:'networkidle'});await mobile.click('#start-button');
  await mobile.keyboard.press('Enter');await mobile.keyboard.press('Enter');
  const stick=mobile.locator('#touch-stick'),rect=await stick.boundingBox();
  await mobile.mouse.move(rect.x+rect.width/2,rect.y+rect.height/2);await mobile.mouse.down();await mobile.mouse.move(rect.x+rect.width*.82,rect.y+rect.height/2,{steps:5});await mobile.waitForTimeout(900);await mobile.mouse.up();
  const mobileAfter=await mobile.evaluate(()=>({x:window.__gameTest?.state?.().player.x,buttons:['#mobile-interact','#mobile-fire','#mobile-run','#touch-stick'].map(s=>[s,getComputedStyle(document.querySelector(s)).display,document.querySelector(s).getBoundingClientRect().width])}));
  console.log(JSON.stringify({start,afterHeal,afterShot,afterReload,save,mobileAfter,errors},null,2));
  await browser.close();
})();

