const {chromium}=require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async()=>{
 const browser=await chromium.launch({headless:true,args:['--use-gl=angle','--use-angle=swiftshader','--enable-unsafe-swiftshader','--no-sandbox']});
 const page=await browser.newPage({viewport:{width:1280,height:720}}),errors=[];page.on('pageerror',e=>errors.push(String(e)));
 await page.route('**/game.js',async route=>{let body=await(await route.fetch()).text();body=body.replace('init();\nfunction startGame','init();window.__gameTest={state:()=>({stage,currentChapter,active,health}),place:(x,z)=>player.position.set(x,0,z),interact,advanceDialogue};\nfunction startGame');await route.fulfill({body,contentType:'text/javascript'});});
 await page.goto('http://localhost:3002/',{waitUntil:'networkidle'});await page.evaluate(()=>localStorage.removeItem('last-sanctuary-save'));await page.reload({waitUntil:'networkidle'});await page.click('#start-button');
 await page.evaluate(()=>{window.__gameTest.advanceDialogue();window.__gameTest.advanceDialogue();});
 const path=[[-14,1],[-1,1],[15,1]],snapshots=[];
 for(let chapter=0;chapter<5;chapter++){
   for(let stage=0;stage<3;stage++){
     await page.evaluate(([x,z])=>{window.__gameTest.place(x,z);window.__gameTest.interact();},path[stage]);
     if(stage<2)await page.evaluate(()=>window.__gameTest.advanceDialogue());
     else if(chapter<4){await page.waitForTimeout(2950);await page.evaluate(()=>window.__gameTest.advanceDialogue());}
     snapshots.push(await page.evaluate(()=>window.__gameTest.state()));
   }
 }
 console.log(JSON.stringify({snapshots,endingVisible:await page.locator('#ending-screen').evaluate(e=>!e.classList.contains('hidden')),errors},null,2));await browser.close();
})();

